      ribbonAiRevisionsTip: "\u0418\u0418 \u0447\u0438\u0442\u0430\u0435\u0442 \u043D\u0435\u0440\u0430\u0441\u0441\u043C\u043E\u0442\u0440\u0435\u043D\u043D\u044B\u0435 \u0438\u0441\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F ({count}), \u0440\u0435\u0437\u044E\u043C\u0438\u0440\u0443\u0435\u0442 \u0438\u0445 \u043F\u043E \u0440\u0430\u0437\u0434\u0435\u043B\u0430\u043C \u0438 \u043E\u0442\u043C\u0435\u0447\u0430\u0435\u0442 \u0440\u0438\u0441\u043A\u0438",
      ribbonAiRevisionsPrompt: "\u0421\u043E\u0441\u0442\u0430\u0432\u044C\u0442\u0435 \u0441\u0432\u043E\u0434\u043A\u0443 \u0432\u0441\u0435\u0445 \u043D\u0435\u0440\u0430\u0441\u0441\u043C\u043E\u0442\u0440\u0435\u043D\u043D\u044B\u0445 \u0438\u0441\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0439 \u0432 \u0434\u043E\u043A\u0443\u043C\u0435\u043D\u0442\u0435: \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u043E\u0431\u0449\u0430\u044F \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043A\u0430 (\u0447\u0438\u0441\u043B\u043E \u0432\u0441\u0442\u0430\u0432\u043E\u043A/\u0443\u0434\u0430\u043B\u0435\u043D\u0438\u0439, \u0430\u0432\u0442\u043E\u0440\u044B, \u0434\u0438\u0430\u043F\u0430\u0437\u043E\u043D \u0434\u0430\u0442), \u0437\u0430\u0442\u0435\u043C \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u044F \u043F\u043E \u0440\u0430\u0437\u0434\u0435\u043B\u0430\u043C (\u0441 \u0443\u043A\u0430\u0437\u0430\u043D\u0438\u0435\u043C \u0438\u043D\u0434\u0435\u043A\u0441\u043E\u0432 \u0431\u043B\u043E\u043A\u043E\u0432), \u0432 \u043A\u043E\u043D\u0446\u0435 \u2014 \u0441\u043F\u0438\u0441\u043E\u043A \u0440\u0438\u0441\u043A\u043E\u0432 (\u0443\u0434\u0430\u043B\u0451\u043D\u043D\u044B\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u0430 \u0438\u043B\u0438 \u043E\u0433\u043E\u0432\u043E\u0440\u043A\u0438, \u0438\u0437\u043C\u0435\u043D\u0451\u043D\u043D\u044B\u0435 \u0447\u0438\u0441\u043B\u0430/\u0434\u0430\u0442\u044B/\u0441\u0443\u043C\u043C\u044B). \u0422\u043E\u043B\u044C\u043A\u043E \u0441\u0432\u043E\u0434\u043A\u0430 \u2014 \u043D\u0435 \u0438\u0437\u043C\u0435\u043D\u044F\u0439\u0442\u0435 \u0434\u043E\u043A\u0443\u043C\u0435\u043D\u0442 \u0438 \u043D\u0435 \u043F\u0440\u0438\u043D\u0438\u043C\u0430\u0439\u0442\u0435/\u043E\u0442\u043A\u043B\u043E\u043D\u044F\u0439\u0442\u0435 \u0438\u0441\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F.",
