      ribbonAiRevisionsPrompt: "\u0644\u062E\u0651\u0635 \u062C\u0645\u064A\u0639 \u0627\u0644\u0645\u0631\u0627\u062C\u0639\u0627\u062A \u0627\u0644\u0645\u0639\u0644\u0642\u0629 \u0641\u064A \u0627\u0644\u0645\u0633\u062A\u0646\u062F: \u0627\u0628\u062F\u0623 \u0628\u0625\u062D\u0635\u0627\u0621\u0627\u062A \u0639\u0627\u0645\u0629 (\u0639\u062F\u062F \u0627\u0644\u0625\u062F\u0631\u0627\u062C\u0627\u062A/\u0627\u0644\u062D\u0630\u0648\u0641\u0627\u062A\u060C \u0627\u0644\u0645\u0624\u0644\u0641\u0648\u0646\u060C \u0646\u0637\u0627\u0642 \u0627\u0644\u062A\u0648\u0627\u0631\u064A\u062E)\u060C \u062B\u0645 \u0627\u0634\u0631\u062D \u0627\u0644\u062A\u063A\u064A\u064A\u0631\u0627\u062A \u0642\u0633\u0645\u064B\u0627 \u0628\u0642\u0633\u0645 (\u0645\u0639 \u0630\u0643\u0631 \u0641\u0647\u0627\u0631\u0633 \u0627\u0644\u0643\u062A\u0644)\u060C \u0648\u0627\u062E\u062A\u0645 \u0628\u0642\u0627\u0626\u0645\u0629 \u0646\u0642\u0627\u0637 \u062A\u0633\u062A\u062F\u0639\u064A \u0627\u0644\u0627\u0646\u062A\u0628\u0627\u0647 (\u062D\u0630\u0641 \u0627\u0644\u062A\u0632\u0627\u0645\u0627\u062A \u0623\u0648 \u0642\u064A\u0648\u062F\u060C \u062A\u063A\u064A\u064A\u0631 \u0623\u0631\u0642\u0627\u0645/\u062A\u0648\u0627\u0631\u064A\u062E/\u0645\u0628\u0627\u0644\u063A). \u0644\u062E\u0651\u0635 \u0641\u0642\u0637 \u2014 \u0644\u0627 \u062A\u0639\u062F\u0651\u0644 \u0627\u0644\u0645\u0633\u062A\u0646\u062F \u0648\u0644\u0627 \u062A\u0642\u0628\u0644 \u0623\u0648 \u062A\u0631\u0641\u0636 \u0623\u064A \u0645\u0631\u0627\u062C\u0639\u0629.",
